    13→namespace Nethermind.Blockchain.BeaconBlockRoot;
    14→public class BeaconBlockRootHandler(ITransactionProcessor processor, IWorldState stateProvider) : IBeaconBlockRootHandler
    15→{
    16→    private const long GasLimit = 30_000_000L;
    17→
    18→    AccessList? IHasAccessList.GetAccessList(Block block, IReleaseSpec spec)
    19→        => BeaconRootsAccessList(block, spec, includeStorageCells: true).accessList;
    20→
    21→    public (Address? toAddress, AccessList? accessList) BeaconRootsAccessList(Block block, IReleaseSpec spec, bool includeStorageCells = false)
    22→    {
    23→        const int HistoryBufferLength = 8191;
    24→
    25→        BlockHeader? header = block.Header;
    26→        bool canInsertBeaconRoot = spec.IsBeaconBlockRootAvailable
    27→                                  && !header.IsGenesis
    28→                                  && header.ParentBeaconBlockRoot is not null;
    29→
    30→        Address? eip4788ContractAddress = canInsertBeaconRoot ?
    31→            spec.Eip4788ContractAddress ?? Eip4788Constants.BeaconRootsAddress :
    32→            null;
    33→
    34→        if (eip4788ContractAddress is null || !stateProvider.AccountExists(eip4788ContractAddress))
    35→        {
    36→            return (null, null);
    37→        }
    38→
    39→        var builder = new AccessList.Builder()
    40→            .AddAddress(eip4788ContractAddress);
    41→
    42→        if (includeStorageCells)
    43→        {
    44→            // https://eips.ethereum.org/EIPS/eip-4788
    45→            // Set the storage value at header.timestamp % HISTORY_BUFFER_LENGTH to be header.timestamp
    46→            ulong slotIndex = header.Timestamp % HistoryBufferLength;
    47→            UInt256 slot256 = slotIndex;
    48→            builder.AddStorage(in slot256);
    49→            // Set the storage value at header.timestamp % HISTORY_BUFFER_LENGTH + HISTORY_BUFFER_LENGTH to be calldata[0:32]
    50→            slot256 = slotIndex + HistoryBufferLength;
    51→            builder.AddStorage(in slot256);
    52→        }
    53→
    54→        return (eip4788ContractAddress, builder.Build());
    55→    }
    56→
    57→    public void StoreBeaconRoot(Block block, IReleaseSpec spec, ITxTracer tracer)
    58→    {
