   856→        protected virtual GasConsumed Refund(Transaction tx, BlockHeader header, IReleaseSpec spec, ExecutionOptions opts,
   857→            in TransactionSubstate substate, in long unspentGas, in UInt256 gasPrice, int codeInsertRefunds, long floorGas)
   858→        {
   859→            long spentGas = tx.GasLimit;
   860→            var codeInsertRefund = (GasCostOf.NewAccount - GasCostOf.PerAuthBaseCost) * codeInsertRefunds;
   861→
   862→            if (!substate.IsError)
   863→            {
   864→                spentGas -= unspentGas;
   865→
   866→                long totalToRefund = codeInsertRefund;
   867→                if (!substate.ShouldRevert)
   868→                    totalToRefund += substate.Refund + substate.DestroyList.Count * RefundOf.Destroy(spec.IsEip3529Enabled);
   869→                long actualRefund = CalculateClaimableRefund(spentGas, totalToRefund, spec);
   870→
   871→                if (Logger.IsTrace)
   872→                    Logger.Trace("Refunding unused gas of " + unspentGas + " and refund of " + actualRefund);
   873→                spentGas -= actualRefund;
   874→            }
   875→            else if (codeInsertRefund > 0)
